insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_EQ_8","title":"¿El total será exactamente 8 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":8},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"TOTAL_EQ_9","title":"¿El total será exactamente 9 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":9},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"TOTAL_EQ_10","title":"¿El total será exactamente 10 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":10},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"TOTAL_EQ_11","title":"¿El total será exactamente 11 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":11},"priority":0,"cooldown":2,"tags":["dificultad"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;